import { useCallback, useState } from 'react';
import { Button, Modal, Stack, Text } from '@jinx-ui/react';

export type DeleteProjectProps = {
  onConfirm: () => void;
};

export default function DeleteProject({ onConfirm }: DeleteProjectProps) {
  const [isOpen, setIsOpen] = useState(false);

  const open = useCallback(() => setIsOpen(true), []);
  const close = useCallback(() => setIsOpen(false), []);

  const confirm = useCallback(() => {
    setIsOpen(false);
    onConfirm();
  }, [onConfirm]);

  return (
    <>
      <Button variant="danger" onClick={open}>
        Удалить проект
      </Button>

      <Modal open={isOpen} onClose={close} title="Удалить проект?">
        <Stack direction="column" gap="var(--jx-space-4)">
          <Text>
            Проект и все связанные с ним данные будут удалены безвозвратно.
            Отменить это действие нельзя.
          </Text>

          <Stack direction="row" gap="var(--jx-space-2)" justify="end">
            <Button variant="secondary" onClick={close}>
              Отмена
            </Button>
            <Button variant="danger" onClick={confirm} autoFocus>
              Удалить проект
            </Button>
          </Stack>
        </Stack>
      </Modal>
    </>
  );
}

